t.script:
document.addEventListener('DOMContentLoaded', function () {
    const dateForm = document.querySelector('.hotel-products-tools.hotel-date-guard-form');
    const dependentLinks = Array.from(document.querySelectorAll('.hotel-date-dependent-link'));

    function listDatesAreValid() {
        if (!dateForm) { return true; }
        const checkinInput = dateForm.querySelector('input[name="checkin"]');
        const checkoutInput = dateForm.querySelector('input[name="checkout"]');
        if (!checkinInput || !checkoutInput || !checkinInput.value || !checkoutInput.value) {
            return false;
        }
        return checkinInput.value < checkoutInput.value;
    }

    function updateDependentLinks() {
        if (!dateForm) { return; }
        const checkinInput = dateForm.querySelector('input[name="checkin"]');
        const checkoutInput = dateForm.querySelector('input[name="checkout"]');
        const adultsInput = dateForm.querySelector('input[name="adults"]');
        const childrenInput = dateForm.querySelector('input[name="children"]');
        const valid = listDatesAreValid();
        const params = new URLSearchParams({
            checkin: checkinInput ? checkinInput.value : '',
            checkout: checkoutInput ? checkoutInput.value : '',
            adults: adultsInput ? adultsInput.value || '2' : '2',
            children: childrenInput ? childrenInput.value || '0' : '0',
        });
        dependentLinks.forEach(function (link) {
            link.classList.toggle('is-disabled', !valid);
            link.setAttribute('aria-disabled', valid ? 'false' : 'true');
            if (valid && link.dataset.roomTypeId) {
                if (link.dataset.linkKind === 'filter') {
                    const filterParams = new URLSearchParams(params);
                    filterParams.set('room_type_id', link.dataset.roomTypeId);
                    link.href = '/hotel?' + filterParams.toString();
                } else if (link.dataset.linkKind === 'detail') {
                    link.href = '/hotel/room/' + link.dataset.roomTypeId + '?' + params.toString();
                }
            }
        });
    }

    if (dateForm) {
        const checkinInput = dateForm.querySelector('input[name="checkin"]');
        const checkoutInput = dateForm.querySelector('input[name="checkout"]');
        const warning = dateForm.querySelector('.hotel-date-warning');
        const submitButtons = Array.from(dateForm.querySelectorAll('[data-date-submit]'));

        function validateListDates() {
            const valid = listDatesAreValid();
            const showWarning = !valid;
            if (warning) {
                warning.classList.toggle('is-visible', showWarning);
            }
            [checkinInput, checkoutInput].forEach(function (input) {
                if (input) {
                    input.classList.toggle('is-invalid', showWarning);
                    input.setCustomValidity(showWarning ? 'Check-out date must be later than the check-in date.' : '');
                }
            });
            submitButtons.forEach(function (button) {
                button.disabled = !valid;
            });
            updateDependentLinks();
            return valid;
        }

        if (checkinInput && checkoutInput) {
            checkoutInput.min = checkinInput.value || checkoutInput.min;
            checkinInput.addEventListener('input', function () {
                checkoutInput.min = checkinInput.value;
                validateListDates();
            });
            checkoutInput.addEventListener('input', validateListDates);
            checkinInput.addEventListener('change', validateListDates);
            checkoutInput.addEventListener('change', validateListDates);
        }

        dateForm.addEventListener('submit', function (event) {
            if (!validateListDates()) {
                event.preventDefault();
                event.stopPropagation();
                if (checkinInput) {
                    checkinInput.focus();
                }
            }
        });
        validateListDates();
    }

    dependentLinks.forEach(function (link) {
        link.addEventListener('click', function (event) {
            if (link.classList.contains('is-disabled') || !listDatesAreValid()) {
                event.preventDefault();
                event.stopPropagation();
                updateDependentLinks();
                const warning = dateForm ? dateForm.querySelector('.hotel-date-warning') : null;
                if (warning) {
                    warning.classList.add('is-visible');
                }
            }
        });
    });
});

function initHotelRoomDetailPage() {
    function and() {
        for (var i = 0; arguments.length > i; i++) {
            if (!arguments[i]) { return false; }
        }
        return arguments[arguments.length - 1];
    }
    function or() {
        for (var i = 0; arguments.length > i; i++) {
            if (arguments[i]) { return arguments[i]; }
        }
        return arguments[arguments.length - 1];
    }

    const isWebsiteEditor = or(
        document.body.classList.contains('editor_enable'),
        document.documentElement.classList.contains('editor_enable'),
        document.body.classList.contains('o_is_editing'),
        document.documentElement.classList.contains('o_is_editing'),
        Boolean(document.querySelector('.o_we_customize_panel')),
        Boolean(document.querySelector('.o_we_customize_panel_wrapper')),
        (window.location.search || '').indexOf('enable_editor=1') !== -1,
        (window.location.search || '').indexOf('edit_translations') !== -1
    );
    // Gallery images swap and prev/next logic
    const gallery = document.querySelector('.hotel-detail-gallery');
    let mainImageField = null;
    let thumbsContainer = null;
    let currentImageIndex = 0;
    if (and(gallery, !isWebsiteEditor)) {
        const mainImage = gallery.querySelector('.hotel-gallery-current');
        mainImageField = mainImage ? mainImage.closest('.hotel-editable-image') : null;
        thumbsContainer = gallery.querySelector('#room-detail-thumbs-container');
        const previousButton = gallery.querySelector('.hotel-gallery-prev');
        const nextButton = gallery.querySelector('.hotel-gallery-next');

        function getThumbnails() {
            return Array.from(gallery.querySelectorAll('.hotel-detail-thumbs img'));
        }

        function normalizeImageIndex(index, total) {
            return ((index % total) + total) % total;
        }

        function setActiveImage(index) {
            const thumbnails = getThumbnails();
            if (or(!mainImage, !thumbnails.length)) { return; }
            currentImageIndex = normalizeImageIndex(index, thumbnails.length);
            gallery.dataset.currentImageIndex = String(currentImageIndex);
            const thumbnail = thumbnails[currentImageIndex];
            const thumbnailField = thumbnail.closest('.hotel-editable-image');
            mainImage.src = thumbnail.dataset.gallerySrc || thumbnail.src;
            mainImage.alt = thumbnail.alt || mainImage.alt;
            if (and(mainImageField, thumbnailField)) {
                ['data-oe-model', 'data-oe-id', 'data-oe-field', 'data-oe-type', 'data-oe-expression'].forEach(function (attribute) {
                    const galleryAttr = attribute.replace('data-oe-', 'data-gallery-oe-');
                    const value = or(thumbnail.getAttribute(galleryAttr), thumbnailField.getAttribute(galleryAttr));
                    if (value) {
                        mainImageField.setAttribute(attribute, value);
                        mainImage.setAttribute(attribute, value);
                    } else {
                        mainImageField.removeAttribute(attribute);
                        mainImage.removeAttribute(attribute);
                    }
                });
            }
            thumbnails.forEach(function (item) {
                const isActive = item === thumbnail;
                item.classList.toggle('is-active', isActive);
                item.setAttribute('aria-current', isActive ? 'true' : 'false');
                const field = item.closest('.hotel-editable-image');
                if (field) {
                    field.classList.toggle('is-active', isActive);
                }
            });
        }

        if (thumbsContainer) {
            thumbsContainer.addEventListener('click', function(event) {
                const img = event.target.closest('img');
                if (and(img, thumbsContainer.contains(img))) {
                    const thumbnails = getThumbnails();
                    const idx = thumbnails.indexOf(img);
                    if (idx !== -1) {
                        setActiveImage(idx);
                    }
                }
            });
        }

        if (previousButton) {
            previousButton.addEventListener('click', function () {
                const storedIndex = parseInt(gallery.dataset.currentImageIndex || '0', 10);
                setActiveImage(storedIndex - 1);
            });
        }
        if (nextButton) {
            nextButton.addEventListener('click', function () {
                const storedIndex = parseInt(gallery.dataset.currentImageIndex || '0', 10);
                setActiveImage(storedIndex + 1);
            });
        }
        setActiveImage(currentImageIndex);
    }

    // Main reactive logic
    const form = document.querySelector('.hotel-detail-book-form');
    if (form) {
        const detailTitle = document.getElementById('detail-room-title');
        const breadcrumbTitle = document.getElementById('breadcrumb-room-name');
        const detailPriceAmount = document.getElementById('detail-price-amount');
        const detailPriceLabel = document.getElementById('detail-price-label');
        const detailCapacity = document.getElementById('detail-capacity-fact');
        const detailAvailable = document.getElementById('detail-available-fact');
        const detailDescriptionContainer = document.getElementById('detail-room-description-container');

        const roomSelect = form.querySelector('[name="room_type_id"]');
        const checkinInput = form.querySelector('input[name="checkin"]');
        const checkoutInput = form.querySelector('input[name="checkout"]');
        const guestsSelect = form.querySelector('select[name="adults"]');
        const breakfastInput = form.querySelector('[name="breakfast_included"]');

        function getSelectedRoomData() {
            const selectedId = roomSelect.value;
            const item = document.querySelector('.room-type-data-item[data-id="' + selectedId + '"]');
            if (!item) return null;
            return {
                id: item.dataset.id,
                name: item.dataset.name,
                price: parseFloat(item.dataset.price || 0),
                capacity: parseInt(item.dataset.capacity || 2),
                available: parseInt(item.dataset.available || 0),
                img1: item.dataset.img1,
                img2: item.dataset.img2,
                img3: item.dataset.img3,
                desc: item.dataset.desc
            };
        }

        function updateSummary() {
            const roomData = getSelectedRoomData();
            if (!roomData) return;

            // Calculate nights
            let nights = 0;
            if (and(checkinInput.value, checkoutInput.value)) {
                const chk = new Date(checkinInput.value);
                const cho = new Date(checkoutInput.value);
                if (cho > chk) {
                    nights = Math.max(1, Math.round((cho - chk) / (1000 * 60 * 60 * 24)));
                }
            }

            const pricePerNight = roomData.price;
            const roomCharges = pricePerNight * nights;
            const adultsCount = parseInt(guestsSelect.value || 1);

            const breakfastPricePerDay = parseFloat(form.dataset.breakfastPrice || 0);
            const isBreakfast = breakfastInput.value === '1';
            const breakfastCharges = isBreakfast ? (breakfastPricePerDay * adultsCount * nights) : 0;
            const grandTotal = roomCharges + breakfastCharges;
            const currencySymbol = form.dataset.currencySymbol || '$';

            const configuredDepositPercent = parseFloat(form.dataset.depositPercent || 0);
            const depositPercent = configuredDepositPercent;
            const depositRequired = and(form.dataset.depositRequired === '1', configuredDepositPercent > 0);
            const depositAmount = depositRequired ? Math.round((grandTotal * configuredDepositPercent / 100) * 100) / 100 : 0;

            // Update summary elements in DOM:
            const sumRoomType = document.getElementById('sum-room-type');
            if (sumRoomType) sumRoomType.textContent = roomData.name;

            const sumCheckin = document.getElementById('sum-checkin');
            if (and(sumCheckin, checkinInput.value)) {
                const d = new Date(checkinInput.value);
                sumCheckin.textContent = d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
            }
            const sumCheckout = document.getElementById('sum-checkout');
            if (and(sumCheckout, checkoutInput.value)) {
                const d = new Date(checkoutInput.value);
                sumCheckout.textContent = d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
            }

            const sumNights = document.getElementById('sum-nights');
            if (sumNights) sumNights.textContent = nights + (nights === 1 ? ' Night' : ' Nights');

            const sumRoomPrice = document.getElementById('sum-room-price');
            if (sumRoomPrice) sumRoomPrice.textContent = '$' + pricePerNight.toFixed(2);

            const sumRoomTotal = document.getElementById('sum-room-total');
            if (sumRoomTotal) sumRoomTotal.textContent = '$' + roomCharges.toFixed(2);

            const sumBreakfastRow = document.getElementById('sum-breakfast-row');
            if (sumBreakfastRow) {
                sumBreakfastRow.style.display = isBreakfast ? 'flex' : 'none';
            }
            const sumBreakfastPrice = document.getElementById('sum-breakfast-price');
            if (sumBreakfastPrice) sumBreakfastPrice.textContent = '$' + breakfastPricePerDay.toFixed(2);

            const sumBreakfastTotal = document.getElementById('sum-breakfast-total');
            if (sumBreakfastTotal) sumBreakfastTotal.textContent = '$' + breakfastCharges.toFixed(2);

            const sumGrandTotal = document.getElementById('sum-grand-total');
            if (sumGrandTotal) sumGrandTotal.textContent = '$' + grandTotal.toFixed(2);

            // Deposit information
            const depositBlock = document.getElementById('hotel-deposit-banner');
            if (depositBlock) {
                depositBlock.style.display = depositRequired ? 'block' : 'none';
            }
            const depositRequirementText = document.getElementById('deposit-banner-percent-label');
            if (depositRequirementText) {
                depositRequirementText.textContent = depositPercent.toFixed(2) + '% deposit required';
            }
            const depositValText = document.getElementById('deposit-banner-text');
            if (depositValText) {
                depositValText.textContent = currencySymbol + depositAmount.toFixed(2) + ' must be paid before this reservation is confirmed.';
            }

            // Hidden inputs for form submission
            const submitDepositInput = form.querySelector('[name="expected_deposit_amount"]');
            if (submitDepositInput) {
                submitDepositInput.value = depositAmount.toFixed(2);
            }
            const submitTotalInput = form.querySelector('[name="website_total_amount"]');
            if (submitTotalInput) {
                submitTotalInput.value = grandTotal.toFixed(2);
            }
        }

        function datesAreValid() {
            if (or(!checkinInput, !checkoutInput)) { return false; }
            if (or(!checkinInput.value, !checkoutInput.value)) { return false; }
            return checkoutInput.value > checkinInput.value;
        }

        function updateRoomDetails() {
            const roomData = getSelectedRoomData();
            if (!roomData) return;

            // Title and breadcrumb
            if (detailTitle) detailTitle.textContent = roomData.name;
            if (breadcrumbTitle) breadcrumbTitle.textContent = roomData.name;

            // Price
            if (detailPriceAmount) {
                detailPriceAmount.textContent = roomData.price > 0 ? ('$' + roomData.price.toFixed(2)) : 'Rate on request';
            }
            if (detailPriceLabel) {
                detailPriceLabel.style.display = roomData.price > 0 ? 'inline' : 'none';
            }

            // Facts
            if (detailCapacity) {
                detailCapacity.innerHTML = ' Capacity: ' + roomData.capacity + ' Guests';
            }
            if (detailAvailable) {
                detailAvailable.innerHTML = ' Available Rooms: ' + roomData.available;
            }

            // Description
            if (detailDescriptionContainer) {
                detailDescriptionContainer.innerHTML = roomData.desc || '';
            }

            // Images Gallery Update
            if (and(mainImageField, thumbsContainer, !isWebsiteEditor)) {
                const mainImg = mainImageField.querySelector('img');
                if (mainImg) {
                    mainImg.src = roomData.img1;
                    mainImg.alt = roomData.name;
                }

                // Re-render thumbnails
                let thumbsHtml = '';
                const imgs = [roomData.img1, roomData.img2, roomData.img3];
                const fields = ['website_image_1', 'website_image_2', 'website_image_3'];
                imgs.forEach(function(url, idx) {
                    const activeClass = idx === 0 ? 'is-active' : '';
                    const ariaCurrent = idx === 0 ? 'true' : 'false';
                    thumbsHtml += '<' + 'div class="hotel-editable-image ' + activeClass + '"' +
                             ' data-gallery-oe-model="hotel.room.type"' +
                             ' data-gallery-oe-id="' + roomData.id + '"' +
                             ' data-gallery-oe-field="' + fields[idx] + '"' +
                             ' data-gallery-oe-type="image"' +
                             ' data-gallery-oe-expression="room_type.' + fields[idx] + '">' +
                            '<' + 'img src="' + url + '"' +
                                 ' alt="' + roomData.name + '"' +
                                 ' class="' + activeClass + '"' +
                                 ' data-gallery-index="' + idx + '"' +
                                 ' aria-current="' + ariaCurrent + '"' +
                                 ' data-gallery-src="' + url + '"' +
                                 ' data-gallery-oe-model="hotel.room.type"' +
                                 ' data-gallery-oe-id="' + roomData.id + '"' +
                                 ' data-gallery-oe-field="' + fields[idx] + '"' +
                                 ' data-gallery-oe-type="image"' +
                                 ' data-gallery-oe-expression="room_type.' + fields[idx] + '"/>' +
                        '<' + '/div>';
                });
                thumbsContainer.innerHTML = thumbsHtml;
                currentImageIndex = 0;
                gallery.dataset.currentImageIndex = '0';
            }

            updateSummary();
        }

        function requiredFieldsAreComplete() {
            const fields = Array.from(form.querySelectorAll('[required]'));
            return fields.every(function (field) {
                return or(field.disabled, String(field.value || '').trim());
            });
        }

        function updateRequiredFieldState(showWarning) {
            const fields = Array.from(form.querySelectorAll('[required]'));
            fields.forEach(function (field) {
                const empty = !String(field.value || '').trim();
                field.classList.toggle('is-invalid', and(showWarning, empty));
            });
            const warning = form.querySelector('[data-contact-warning]');
            if (warning) {
                warning.classList.toggle('is-visible', showWarning);
            }
        }

        function emailIsValid() {
            const emailInput = form.querySelector('input[name="guest_email"]');
            if (!emailInput || !String(emailInput.value || '').trim()) {
                return true;
            }
            return emailInput.checkValidity();
        }

        function updateEmailFieldState(showWarning) {
            const emailInput = form.querySelector('input[name="guest_email"]');
            const valid = emailIsValid();
            if (emailInput) {
                emailInput.classList.toggle('is-invalid', and(showWarning, !valid));
            }
            const warning = form.querySelector('[data-email-warning]');
            if (warning) {
                warning.classList.toggle('is-visible', and(showWarning, !valid));
            }
        }

        function updateFormState() {
            const datesValid = datesAreValid();
            const requiredComplete = requiredFieldsAreComplete();
            const emailValid = emailIsValid();
            const warning = form.querySelector('.hotel-date-warning');
            const showWarning = and(checkinInput, checkoutInput, checkinInput.value, checkoutInput.value, !datesValid);
            if (warning) {
                warning.classList.toggle('is-visible', showWarning);
            }
            [checkinInput, checkoutInput].forEach(function (input) {
                if (input) {
                    input.classList.toggle('is-invalid', showWarning);
                    input.setCustomValidity(showWarning ? 'Check-out date must be later than the check-in date.' : '');
                }
            });
            const submitButton = form.querySelector('[data-date-submit]');
            if (submitButton) {
                submitButton.disabled = or(!datesValid, !requiredComplete, !emailValid);
            }
            if (requiredComplete) {
                updateRequiredFieldState(false);
            }
            if (emailValid) {
                updateEmailFieldState(false);
            }
            updateSummary();
            return and(datesValid, requiredComplete, emailValid);
        }

        // Attach Event Listeners
        if (roomSelect.tagName === 'SELECT') {
            roomSelect.addEventListener('change', updateRoomDetails);
        }

        if (and(checkinInput, checkoutInput)) {
            checkinInput.addEventListener('input', updateFormState);
            checkoutInput.addEventListener('input', updateFormState);
            checkinInput.addEventListener('change', updateFormState);
            checkoutInput.addEventListener('change', updateFormState);
        }
        guestsSelect.addEventListener('change', updateSummary);
        if (breakfastInput.tagName === 'SELECT') {
            breakfastInput.addEventListener('change', updateSummary);
        }

        const fieldsToWatch = Array.from(form.querySelectorAll('[required]'));
        fieldsToWatch.forEach(function (field) {
            field.addEventListener('input', updateFormState);
            field.addEventListener('change', updateFormState);
        });
        const emailInput = form.querySelector('input[name="guest_email"]');
        if (emailInput) {
            emailInput.addEventListener('input', updateFormState);
            emailInput.addEventListener('change', updateFormState);
        }

        // Initial loads
        updateRoomDetails();
        updateFormState();

        form.addEventListener('submit', function (event) {
            if (!updateFormState()) {
                event.preventDefault();
                event.stopPropagation();
                if (and(checkinInput, checkoutInput, checkinInput.value, checkoutInput.value, !datesAreValid())) {
                    checkinInput.focus();
                } else {
                    const required = Array.from(form.querySelectorAll('[required]'));
                    const emptyRequired = required.find(function (field) {
                        return !String(field.value || '').trim();
                    });
                    if (emptyRequired) {
                        updateRequiredFieldState(true);
                        emptyRequired.focus();
                    } else if (!emailIsValid()) {
                        updateEmailFieldState(true);
                        const emailInput = form.querySelector('input[name="guest_email"]');
                        if (emailInput) {
                            emailInput.focus();
                        }
                    }
                }
            }
        });
    }
}

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initHotelRoomDetailPage);
} else {
    initHotelRoomDetailPage();
}
